import{G as e,W as t,rt as n,t as r}from"./chunks/framework.3zKPIMIf.js";var i=JSON.parse(`{"title":"判定のしくみ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/how-it-works.md","filePath":"ja/how-it-works.md"}`),a={name:`ja/how-it-works.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="判定のしくみ" tabindex="-1">判定のしくみ <a class="header-anchor" href="#判定のしくみ" aria-label="Permalink to “判定のしくみ”">​</a></h1><p>cBlockは次の4つのしくみで中国語・中国系のコンテンツを見つけて非表示にします。判定はすべてブラウザの中で行います。</p><table tabindex="0"><thead><tr><th>しくみ</th><th>判定に使うもの</th></tr></thead><tbody><tr><td><a href="#テキストフィルター">テキストフィルター</a></td><td>ページの文字と中国系Webサイトへのリンク</td></tr><tr><td><a href="#名称フィルター">名称フィルター</a></td><td>中国系の企業や製品の名前</td></tr><tr><td><a href="#webサイト別スクリプト">Webサイト別スクリプト</a></td><td>出品者、ゲームの開発元、投稿者、作者、ページ自体の文字</td></tr><tr><td><a href="#ドメインブロック">ドメインブロック</a></td><td>開こうとしているページのドメイン</td></tr></tbody></table><h2 id="中国系の企業とwebサイト" tabindex="-1">中国系の企業とWebサイト <a class="header-anchor" href="#中国系の企業とwebサイト" aria-label="Permalink to “中国系の企業とWebサイト”">​</a></h2><p>中国系の企業は次のいずれかに当てはまる企業です。登記した国は問いません。</p><ul><li>中国本土で創業した企業</li><li>経営や開発の主な拠点が中国本土にある企業</li></ul><p>中国の企業から出資を受けているだけの企業は含めません。対象は中国本土だけで、香港とマカオの企業や出品者、アカウントは含めません。ただし、中国本土の電話番号や接続元などの手がかりがあれば含めます。</p><p>中国系Webサイトとは、中国で創業した企業や中国を拠点とする企業のWebサイトと <code>.cn</code>、<code>.中国</code>、または <code>.中國</code> ドメインのWebサイトです。</p><p><a href="/ja/companies">中国系の企業の一覧</a>に、各企業のWebサイトとcBlockが探す名前を載せています。</p><h2 id="テキストフィルター" tabindex="-1">テキストフィルター <a class="header-anchor" href="#テキストフィルター" aria-label="Permalink to “テキストフィルター”">​</a></h2><p>設定の「中国語のテキスト」と「中国系Webサイトへのリンク」で動作します。どちらも初期設定でオンです。</p><h3 id="読み取る文字" tabindex="-1">読み取る文字 <a class="header-anchor" href="#読み取る文字" aria-label="Permalink to “読み取る文字”">​</a></h3><ul><li>ページに表示されている文字</li><li>画像の代替テキスト（<code>alt</code>）、ツールチップ（<code>title</code>）、読み上げ用のラベル（<code>aria-label</code>、<code>aria-description</code>）</li></ul><p>次の要素の中の文字は読みません。</p><ul><li>入力欄（<code>input</code>、<code>textarea</code>）と編集できる欄（<code>contenteditable</code>）</li><li>プログラムのコード（<code>code</code>、<code>pre</code>）</li><li>スクリプトとスタイル（<code>script</code>、<code>style</code>）、ページの情報（<code>head</code>）</li></ul><h3 id="中国語の判定" tabindex="-1">中国語の判定 <a class="header-anchor" href="#中国語の判定" aria-label="Permalink to “中国語の判定”">​</a></h3><p>段落やリスト項目のような文字のまとまり（以下、ブロック）ごとに次の順で判定します。</p><ol><li>漢字を含まないブロックは中国語と判定しません。</li><li>ページが <code>lang=&quot;zh-TW&quot;</code> で台湾の中国語と示している部分は中国語として扱いません。</li><li>ページが <code>lang=&quot;zh-CN&quot;</code> のように中国語と示している部分は中国語とします。</li><li>仮名（ひらがな、カタカナ）を含むブロックは日本語とします。ただし、仮名で区切った部分のどれかに日本語にない漢字が2種類以上あれば中国語とします。</li><li>仮名を含まないブロックは、次のいずれかに当てはまれば中国語とします。 <ul><li>日本語にない漢字が1字以上ある（例: 们、这、说）</li><li>中国語でよく使い、日本語ではほとんど使わない字や語がある（例: 很、什麼、沒有、有限公司）</li><li>漢字が10種類以上あり、そのうち2種類以上が第1水準漢字ではない（例: 國、體）</li></ul></li></ol><blockquote><p>「日本語にない漢字」は、日本語の文字コード（JIS X 0208、JIS X 0212、Shift_JIS）にない漢字です。「第1水準漢字」は、JIS X 0208のうち日常よく使う2,965字です。</p></blockquote><h3 id="繁体字の判定" tabindex="-1">繁体字の判定 <a class="header-anchor" href="#繁体字の判定" aria-label="Permalink to “繁体字の判定”">​</a></h3><p>「繁体字の中国語を表示」をオンにすると、中国語と判定したブロックのうち簡体字のものだけを非表示にします。初期設定ではオフです。</p><ol><li>ページが <code>lang</code> で繁体字（<code>zh-Hant</code>、<code>zh-TW</code>、<code>zh-HK</code>、<code>zh-MO</code>）と示していれば繁体字とします。</li><li>簡体字（<code>zh-Hans</code>、<code>zh-CN</code>、<code>zh-SG</code>）と示していれば簡体字とします。</li><li>どちらも示していなければ字で見分けます。繁体字だけで使う字があり、簡体字だけで使う字がなければ繁体字とします。</li><li>それ以外は簡体字とします。両方の字を含むブロックと、どちらも含まないブロックが当てはまります。</li></ol><table tabindex="0"><thead><tr><th>字の種類</th><th>条件</th><th>例</th></tr></thead><tbody><tr><td>簡体字だけで使う字</td><td>GB2312にあり、Big5と日本語の文字コードにない字</td><td>们、这、说</td></tr><tr><td>繁体字だけで使う字</td><td>Big5の常用字にあり、GB2312にない字</td><td>們、這、說</td></tr></tbody></table><blockquote><p>GB2312は中国本土の文字コード、Big5は台湾と香港の文字コードです。</p></blockquote><h3 id="非表示にする範囲" tabindex="-1">非表示にする範囲 <a class="header-anchor" href="#非表示にする範囲" aria-label="Permalink to “非表示にする範囲”">​</a></h3><ul><li>中国語と判定したブロックを含む投稿、カード、リスト項目を非表示にします。</li><li>2,000字を超えるブロックは判定しません（ページの大部分を非表示にしないため）。</li><li>レイアウトを崩さないよう、次のWebサイトでは非表示にする単位をWebサイトごとにあらかじめ設定しています（例: YouTubeの動画1本、検索結果の1件）。 <ul><li>YouTube、Reddit、X、TVer、pixiv、Wikipedia、Yahoo!ニュース、楽天市場、GitHub、Hacker News</li><li>Google（google.com、google.co.jp）、Bing、DuckDuckGo、Yahoo! JAPAN、Yahoo（米国）、Brave、Ecosia、Startpage</li><li>Impress Watch、ファミ通.com</li></ul></li></ul><h3 id="中国系webサイトへのリンク" tabindex="-1">中国系Webサイトへのリンク <a class="header-anchor" href="#中国系webサイトへのリンク" aria-label="Permalink to “中国系Webサイトへのリンク”">​</a></h3><p>表示中のWebサイト以外の中国系Webサイトへのリンクを周りのカードごと非表示にします。カードが見つからなければリンクだけを非表示にします。</p><h3 id="言語を問わず非表示にするもの" tabindex="-1">言語を問わず非表示にするもの <a class="header-anchor" href="#言語を問わず非表示にするもの" aria-label="Permalink to “言語を問わず非表示にするもの”">​</a></h3><p>「中国語のテキスト」がオンのとき、次のものも非表示にします。</p><table tabindex="0"><thead><tr><th>Webサイト</th><th>非表示にするもの</th></tr></thead><tbody><tr><td>X</td><td>「中国語からの翻訳」（英語表示では「Translated from Chinese」）と表示されたポスト</td></tr><tr><td>TVer</td><td>題名が「中国ドラマ」「中国時代劇」「中国映画」「中国アニメ」「華流」で始まる番組</td></tr></tbody></table><h2 id="名称フィルター" tabindex="-1">名称フィルター <a class="header-anchor" href="#名称フィルター" aria-label="Permalink to “名称フィルター”">​</a></h2><p>設定の「中国系の企業や製品の名前」で動作します。初期設定ではオフです。</p><p>cBlockは中国系の企業や製品の名前の一覧（以下、名称一覧）を搭載しています。オンにすると、名称一覧にある名前が出てくるブロックをどのWebサイトでも非表示にします。</p><h3 id="名前の照合" tabindex="-1">名前の照合 <a class="header-anchor" href="#名前の照合" aria-label="Permalink to “名前の照合”">​</a></h3><ul><li>英字の名前は単語として照合し、大文字と小文字を区別しません。後ろに数字が続いても一致します（例: Qwen3）。</li><li>短い名前やほかの語と紛らわしい名前は、大文字と小文字まで同じときだけ一致します（例: TCL、BYD、ERNIE）。</li><li>仮名や漢字の名前は文の途中にあっても一致します（例: 原神）。</li></ul><h3 id="ほかの意味もある名前" tabindex="-1">ほかの意味もある名前 <a class="header-anchor" href="#ほかの意味もある名前" aria-label="Permalink to “ほかの意味もある名前”">​</a></h3><p>アリババやvivoのようにほかの意味もある名前は、同じブロックに次の手がかりがもう1つあるときだけ非表示にします。「アリババグループ」のように企業を指すとわかる名前は、手がかりがなくても非表示にします。</p><ul><li>名称一覧にあるほかの名前（ほかの意味もある名前を除く）</li><li>中国を表す語（中国、中華、China、Chinese）</li><li>その企業に関わる語（例: アリババなら「決算」「株価」「ジャック・マー」）</li></ul><h2 id="webサイト別スクリプト" tabindex="-1">Webサイト別スクリプト <a class="header-anchor" href="#webサイト別スクリプト" aria-label="Permalink to “Webサイト別スクリプト”">​</a></h2><p>ページの文字だけではわからないことをWebサイトごとの方法で調べます。</p><ul><li>「Webサイトへの問い合わせ」はWebサイトごとにオンにでき、初期設定ではすべてオフです。</li><li>問い合わせは画面内とその少し先にある項目についてだけ行います。</li><li>問い合わせの結果はブラウザに30日間保存し、同じ問い合わせを繰り返しません。</li><li>Webサイトがエラーを返したときは一定期間（5分以上）問い合わせを停止します。</li></ul><h3 id="amazon" tabindex="-1">Amazon <a class="header-anchor" href="#amazon" aria-label="Permalink to “Amazon”">​</a></h3><p>商品名に名称一覧の中国系ブランド名があれば、その商品を非表示にします。商品ページではページ本体を非表示にします。</p><ul><li>amazon.co.jp、amazon.com、amazon.co.ukで動作します。</li><li>商品名の中の名前はブランド名を指すため、<a href="#ほかの意味もある名前">ほかの意味もある名前</a>も手がかりなしで非表示にします。</li><li>検索結果の絞り込み欄にある中国系ブランドの項目も非表示にします。</li></ul><div class="info custom-block"><p class="custom-block-title">「Webサイトへの問い合わせ」がオンのとき</p><p>出品者の情報ページを読み、次のいずれかに当てはまる出品者の商品を非表示にします。</p><ul><li>住所の国が中国（<code>CN</code>）</li><li>電話番号が中国の国番号（+86）で始まる</li><li>運営責任者名（amazon.co.jp）の表記がピンイン（中国語のローマ字表記）か中国語</li><li>販売業者名の表記が中国語か、ピンインの「有限公司」（youxian gongsi）</li><li>登録番号（amazon.co.uk）が中国の統一社会信用コードの形式</li></ul><blockquote><ul><li>住所が台湾、香港、マカオの出品者には、名前と登録番号による判定を使いません。</li><li>出品者の名前の判定には「繁体字の中国語を表示」を適用しません。</li><li>判定済みの出品者は絞り込み欄の項目も非表示にします。</li><li>Amazonが確認画面（CAPTCHA）を出したときは問い合わせを10分間停止します。</li></ul></blockquote></div><h3 id="steam" tabindex="-1">Steam <a class="header-anchor" href="#steam" aria-label="Permalink to “Steam”">​</a></h3><p>開発元かパブリッシャーが中国系のスタジオのゲームを非表示にします。「Webサイトへの問い合わせ」がオフのときはゲームのページだけを非表示にします。</p><ul><li>社名の「Ltd.」のような語尾は無視し、残りが完全に一致したときだけ非表示にします。</li><li>中国の企業から出資を受けているだけのスタジオは含めません。</li></ul><div class="info custom-block"><p class="custom-block-title">「Webサイトへの問い合わせ」がオンのとき</p><p>検索結果、トップページ、カテゴリーやキュレーターのページにあるゲームのカードも非表示にします。カードのゲームごとに開発元とパブリッシャーをSteamに問い合わせます。</p></div><h3 id="x" tabindex="-1">X <a class="header-anchor" href="#x" aria-label="Permalink to “X”">​</a></h3><p>中国政府の省庁と報道官、大使館、領事館、大使、国営メディアとその編集者など、決まった約50のアカウントのポストを非表示にします。</p><div class="info custom-block"><p class="custom-block-title">「Webサイトへの問い合わせ」がオンのとき</p><p>テキストフィルターが表示したポストのうち、次のポストの投稿者を調べます。</p><ul><li><code>lang</code> が中国語のポスト</li><li>漢字があって仮名がないポスト</li></ul><p>Xの「このアカウントについて」で調べ、「アカウントの所在地」か「接続元」が中国なら、その投稿者のポストをすべて非表示にします。</p><blockquote><p>Xの問い合わせ回数の上限（15分あたり50件）が残り5件になると、上限が戻るまで問い合わせを停止します。</p></blockquote></div><h3 id="pixiv" tabindex="-1">pixiv <a class="header-anchor" href="#pixiv" aria-label="Permalink to “pixiv”">​</a></h3><p>作品か作者が下の基準に当てはまれば、その作品や作者のカードとコメントを非表示にします。作品ページと作者のプロフィールページではページ本体を非表示にします。</p><p>作品は次の順で判定し、中国語なら非表示にします。</p><ol><li>小説の言語が中国語（台湾の中国語を除く）なら中国語とします。言語を表すタグ（中国語、中文、简体中文）がある作品も同じです。</li><li>題名が中国語なら中国語、仮名を含めば日本語とします。</li><li>題名でわからなければ、中国語のタグが仮名を含むタグより多いとき中国語とします。</li></ol><p>作者は次のように判定します。</p><ul><li>同じ作者の作品が2件以上表示され過半数が中国語なら、その作者の作品をすべて非表示にします。</li><li>プロフィールページでpixivが読み込んだプロフィールが次のいずれかに当てはまれば、その作者の作品を非表示にします。 <ul><li>地域が中国</li><li>自己紹介が主に中国語で、地域が香港、マカオ、台湾ではない</li><li>中国系Webサイトへのリンクか中国系のメールアドレス（例: @qq.com）があり、自己紹介が主に日本語ではない</li></ul></li><li>プロフィールに載せたXアカウントがXの問い合わせで中国と判定済みなら、その作者の作品を非表示にします。</li></ul><blockquote><p>中国語の行が仮名を含む行より多いとき、自己紹介を「主に中国語」とします。</p></blockquote><div class="info custom-block"><p class="custom-block-title">「Webサイトへの問い合わせ」がオンのとき</p><p>プロフィールページ以外でも表示中の作品の作者のプロフィールを取得し、上の基準で判定します。</p></div><h3 id="github" tabindex="-1">GitHub <a class="header-anchor" href="#github" aria-label="Permalink to “GitHub”">​</a></h3><p>「中国語のテキスト」がオンのとき、ページ自体の文字が中国語ならページ本体を非表示にします。</p><ul><li>リポジトリは説明で、issue、プルリクエスト、ディスカッションは題名で判定します。</li><li>リポジトリのトップページではREADMEの行の半分を超えて中国語のときも非表示にします。英語のREADMEに「简体中文」のリンクが1行あるだけでは非表示にしません。</li><li>検索結果、一覧の行、コメントはテキストフィルターで1件ずつ非表示にします。</li></ul><h2 id="ドメインブロック" tabindex="-1">ドメインブロック <a class="header-anchor" href="#ドメインブロック" aria-label="Permalink to “ドメインブロック”">​</a></h2><p>設定の「中国系Webサイトのページをブロック」で動作します。初期設定でオンです。</p><ul><li>中国系Webサイトのページを読み込む前にブロックします。ページに埋め込まれた別のページ（フレーム）もブロックします。</li><li>画像やスクリプトはブロックしません。</li><li>ドメインの末尾で判定します。<code>bilibili.com</code> と <code>www.bilibili.com</code> はブロックしますが、<code>bilibili.com.example.org</code> はブロックしません。</li><li><code>.cn</code>、<code>.中国</code>、または <code>.中國</code> のWebサイトはすべてブロックします。<code>example.cn</code> はブロックしますが、<code>example.cn.com</code> や <code>cn.bing.com</code> はブロックしません。</li><li>ポップアップでWebサイトをオフにしても、ブロックは続きます。止めるにはこの設定かcBlock自体をオフにします。</li></ul><h2 id="判定の限界" tabindex="-1">判定の限界 <a class="header-anchor" href="#判定の限界" aria-label="Permalink to “判定の限界”">​</a></h2><ul><li>台湾、香港、マカオの繁体字も初期設定では非表示にします。<code>lang=&quot;zh-TW&quot;</code> と示した部分だけは表示します。</li><li>「繁体字の中国語を表示」をオンにしても、文字だけでは台湾の文と香港の文を見分けられません。</li><li>珍しい漢字（例: 剝、幷）を使った日本語の文を誤って非表示にすることがあります。特に仮名を含まない短い文で起こります。</li><li>日本語の文字コードにある漢字だけで書いた短い中国語（例: 原神官網）は、非表示にしないことがあります。</li><li>英語やピンインで書いた中国のページは、ドメインがブロックの対象でなければ非表示にしません。</li><li>中国を拠点とする企業やアカウントが日本語や英語で書いた文は、テキストフィルターでは見分けられません。</li></ul>`,69)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};